=== Method: calc (AbstractMethod) ===
/*CSM Rollout with option of different characteristic of pressure build up*/
/**************************************************************************/
/*The rollout logic becomes active in an uphill situation if the vehicle  */
/*is almost in standstill, but current brake pressure is not high enough  */
/*to hold the vehicle at current slope. Goal of this class is to          */
/*calculate the:                                                          */
/* - optimal time point to start with the brake pressure increase   	  */
/*  and related target values											  */
/**************************************************************************/

// Determine which should be the considered brake pressure for rollout calculation
if(CsmHoldRolloutActive == false
	&& OperationPointConsiderSyst)
{
	ABrkAct = (((CsmHoldATarBrk).min(ABrkDrv)).min(CsmAActConfirmedReq)).min(ABrkSys);
}
else
{
	ABrkAct = (((CsmHoldATarBrk).min(ABrkDrv)).min(CsmAActConfirmedReq));
}

// Get reference value for maximum volume flow
if(FS_CSM_HoldConsiderNPumo)
{
	CSM_nPumo2q.calc(C_CSM_BrakeNPumoRef);
	q_MaxBrkIncRefBrake = CSM_nPumo2q.qBrake();
}else
{
	q_MaxBrkIncRefBrake = C_CSM_BrakeQMaxBrkIncRef;
}

// Get value for start volume flow
if(FS_CSM_HoldConsiderNPumo)
{
	CSM_nPumo2q.calc(C_CSM_RolloutNPumoStart.getAt(ASlopeInSelMovDir));
	q_StartRollout = CSM_nPumo2q.qBrake();
}else
{
	q_StartRollout = C_CSM_RolloutQStart;
}

// Get value for maximum volume flow
if(FS_CSM_HoldConsiderNPumo)
{
	CSM_nPumo2q.calc(C_CSM_RolloutNPumoMax);
	q_MaxRollout = CSM_nPumo2q.qBrake();
}else
{
	q_MaxRollout = C_CSM_RolloutQMax;
}

// Get value for minimum volume flow
if(FS_CSM_HoldConsiderNPumo)
{
	CSM_nPumo2q.calc(C_CSM_RolloutNPumoMin);
	q_MinRollout = CSM_nPumo2q.qBrake();
}else
{
	q_MinRollout = C_CSM_RolloutQMin;
}
/***********************************************************************************************/
//Calculate charactersitics of Brake Actuator (without considering any active valve strategies)
// i.e. Reference Curve
/***********************************************************************************************/

CSM_ActuatorModel.calc(100,q_MaxBrkIncRefBrake, C_BrakeSystemReferenceMass, 100, CycleTime);

/************************************************/
//Extract aTar for Rollout (aTarReachStandstill)
/************************************************/

//Determine the required offset values
aOffsetReachStandstill = C_CSM_RolloutATarOffsetAbs.getAt(AVehForTarget) + C_CSM_RolloutATarOffsetMap.getAt(ASlopeInSelMovDir);
aOffsetAfterStandstill = C_CSM_RolloutATarStandstillOffset.getAt(ASlopeInSelMovDir.abs()).min(aOffsetReachStandstill);


//Considered target brake force required at time of reaching standstill
//i.e.deceleration which should be reached with the rollout
aTarReachStandstill = (aOffsetReachStandstill + ((AVehForTarget).min(0))).min(0);

//get propulsion at rollout start.
RolloutStart.calc(CsmHoldRolloutActive);
if (RolloutStart.out())
{
	AActPropStart = APropAct;
}
else{}//do nothing

/*************************************************************************************/
//Determine time tresholds for final rollout trigger and determine possible adjustment
/*************************************************************************************/
if	(	(CsmHoldRolloutActive == false) //prepare for rollout
	||	(APropAct < AActPropStart - C_CSM_RolloutAPropDeltaRecalc)
	||	((EnableQRequiredAdjustment == true)
		&&(CsmHoldRolloutATarBrk > aTarReachStandstill) //only allow readjustment if vehicle is still moving
		)
	)
{
	// Calculate ratio of reference to target volume flow.
	q_RatioRefToTgt = q_MaxBrkIncRefBrake/(q_MaxRollout.min(q_StartRollout.max(q_MinRollout)));

	CSM_ActuatorModel.tBrake(aTarReachStandstill*q_RatioRefToTgt);
	t_pTar = CSM_ActuatorModel.tBrakeGet();			//get time from reference curve for build up duration
	CSM_ActuatorModel.tBrake(ABrkAct*q_RatioRefToTgt);
	t_pCur = CSM_ActuatorModel.tBrakeGet();			//get time from reference curve for build up duration
	tReaction = C_CSM_RolloutTReaction.getAt(ASlopeInSelMovDir);
	timeRequiredForTarget = (t_pTar - t_pCur + tReaction).max(0); 	//time extracted from reference + deadtime
	
	CSM_ActuatorModel.vBrake(aTarReachStandstill*q_RatioRefToTgt);
	v_pTar = CSM_ActuatorModel.vBrakeGet(); 		//get start velocity for build up considering reference curve
	CSM_ActuatorModel.vBrake(ABrkAct*q_RatioRefToTgt);
	v_pCur = CSM_ActuatorModel.vBrakeGet(); 		//get start velocity for build up considering reference curve
	vVehAtRolloutStart = (v_pTar*1/q_RatioRefToTgt - v_pCur*1/q_RatioRefToTgt).max(0); 	//reference velocity at start converted to target at start
	
	if (FS_CSM_CompensateRolloutDecel)
	{	//
		timeToStandstillExpected = ((vVeh - vVehAtRolloutStart).max(0))/((AVehForTrigger.min(-0.001)).abs()); //considering impact of rollout deceleration
	}
	else
	{
		timeToStandstillExpected = vVeh/((AVehForTrigger.min(-0.001)).abs()); //only current velocity and deceleration considered, rollout impact not compensated
	}
	
	
	CSM_ActuatorModel.tBrake(ABrkAct);
	t_pCurRef = CSM_ActuatorModel.tBrakeGet();			//get time from reference curve for build up duration
	//determine required volume flow for given expected time to standstill
	CSM_ActuatorModel.aBrake((timeToStandstillExpected - tReaction + t_pCurRef).max(t_pCurRef));
	aReachableExpected = CSM_ActuatorModel.aBrakeGet().min(-0.001);
	qRolloutRequired = q_MaxBrkIncRefBrake*aTarReachStandstill/aReachableExpected;
	
	// Calculate adjusted ratio of reference to target volume flow.
	q_RatioRefToTgt = q_MaxBrkIncRefBrake/((q_MaxRollout).min(qRolloutRequired.max(q_MinRollout)));

}
else
{
	tReaction = (tReaction - CycleTime).max(0);
}

/*******************************/
//activation handler
/*******************************/
defaultRolloutTrigger = (	timeRequiredForTarget >= timeToStandstillExpected	// default: time required for increase equals time expected to reach standstill
							&&	vVeh_K1 > vVeh);								// default: velocity decreasing - deceleration
							
if	(	//mandatory: rollout is enabled
	CsmRolloutEnabled == true	
		//AND default condition
	&&	(	defaultRolloutTrigger
		//OR special cases	
		||	(VehMovAgainstIntendedValid == false && vVeh <= C_CSM_RolloutVMoving) 	// case 1: no direction info and velocity lower than threshold
		||	(VehStop == true)														//case 2: Stop anchor
		||	(VehMovAgainstIntendedValid == true && VehMovAgainstIntended == true && VehMovAgainstIntendedK1 == false) // case 3: Rollback anchor
		||	(AVehForTriggerK1 >= C_CSM_RolloutAVehMin.min(0) && defaultRolloutTrigger)) //case 4: vehicle aborting intend to drive off
		// mandatory: vehicle deceleration (based on wss derivative and slope vs PT difference) detected
	&&	AVehForTrigger < C_CSM_RolloutAVehMin.min(0)
		// mandatory: rollout only required in case target not reached yet
	&&	ABrkAct > ((CsmHoldABrkThrMax + (C_CSM_RolloutATarTriggerOffset.getAt(ASlopeInSelMovDir.abs()))).min(aTarReachStandstill))
	)
{
	if	(CsmHoldRolloutActive == false
		&&	(	(qRolloutRequired > (q_StartRollout + C_CSM_qOffsetCritical))
			||	vVeh <= C_CSM_RolloutVMoving)
		)	
	{
		EnableQRequiredAdjustment = true; // target volume flow or nPumo not sufficient to prevent rolling back
	}
	else{} //do nothing
	CsmHoldRolloutActive = true;
}
//maintain rollout active until target hold level is reached
else if(	CsmHoldRolloutActive  == true
		&&	CsmRolloutEnabled == true
		&&	(CsmHoldRolloutATarBrk.max(ABrkSys)) > (CsmHoldABrkThrMax + aOffsetAfterStandstill)
		)
{
	CsmHoldRolloutActive = true;
}
//end rollout phase
else
{
	CsmHoldRolloutActive = false;
	EnableQRequiredAdjustment = false;
}

/*******************************/
//determine final request
/*******************************/
if(CsmHoldRolloutActive == true)
{
	if(CsmHoldRolloutActiveK1 == false)
	{
		CsmHoldRolloutATarBrk = ABrkAct;
	}
	CsmHoldRolloutJTarBrk = JMinRef * 1/q_RatioRefToTgt;
	CsmHoldRolloutATarBrk += CsmHoldRolloutJTarBrk * CycleTime;
}else
{
	CsmHoldRolloutJTarBrk = 0;
	CsmHoldRolloutATarBrk = 0;
	q_Rollout = 0;
}

/*******************************/
//secure HW limit
/*******************************/
if (CsmHoldRolloutATarBrk <= CsmHoldATarThermLimit) // hw limit reached
{
	CsmHoldRolloutActive = false;
	CsmHoldRolloutJTarBrk = 0;
	CsmHoldRolloutATarBrk = 0;
	q_Rollout = 0;
}
else {} // do nothing

/*******************************/
//set k1 values
/*******************************/
VehMovAgainstIntendedK1 = VehMovAgainstIntended;
vVeh_K1 = vVeh;
CsmHoldRolloutActiveK1 = CsmHoldRolloutActive;
AVehForTriggerK1 = AVehForTrigger;


=== Method: CsmHoldRolloutActive (AbstractMethod) ===
return CsmHoldRolloutActive;


=== Method: CsmHoldRolloutATarBrk (AbstractMethod) ===
return CsmHoldRolloutATarBrk;
